#region Search / Filter Functions

private void LoadSearchData(object yearID, object semester)
{
    if (objUser == null || yearID == null || semester == null)
    {
        this.DtbClassSubject = null;
        return;
    }

    SIM_Branch obj = new SimsObject.SIM_Branch();
    DataTable dtbClassSubject = obj.GetDataTable("SIM_Class_Subject_SearchForTeacherInputMark",
                                                    "@YearID", yearID,
                                                    "@Semester", semester,
                                                    "@LoginName", objUser.UserName);
    if (dtbClassSubject != null)
    {
        this.DtbClassSubject = dtbClassSubject;
        this.DtbScience = Libs.MyLibs.GetDataTable(dtbClassSubject, "ScienceID");
        this.DtbClass = Libs.MyLibs.GetDataTable(dtbClassSubject, "ClassID");

        WebGlobal.InitDropDownList(ddlScienceID, this.DtbScience, BO.SIM_Science.C_SCIENCEID, BO.SIM_Science.C_SCIENCENAME, "--Chọn--");

        FilterCourse();
        FilterClass();
        FilterClassSubject();
    }
}

public void FilterCourse()
{
    string strCondition = null;
    if (ddlScienceID.SelectedIndex > 0)
        strCondition = "ScienceID = '" + ddlScienceID.SelectedValue + "'";

    this.DtbCourse = Libs.MyLibs.GetDataTable(this.DtbClass, "CourseID", strCondition);
    WebGlobal.InitDropDownList(ddlCourseID, this.DtbCourse, BO.SIM_Course.C_COURSEID, BO.SIM_Course.C_COURSENAME, "--Chọn--");
}

private void FilterClass()
{
    string strCondition = null;
    if (ddlScienceID.SelectedIndex > 0)
        strCondition = " And ScienceID = '" + ddlScienceID.SelectedValue + "'";
    if (ddlCourseID.SelectedIndex > 0)
        strCondition += " And CourseID = '" + ddlCourseID.SelectedValue + "'";

    if (strCondition != null)
        strCondition = strCondition.Substring(5);
    else
        strCondition = "";

    WebGlobal.InitDropDownList(ddlClassID, this.DtbClass, SIM_Class.C_ClassID, SIM_Class.C_ClassName, "--Chọn--", strCondition);
}

private void FilterClassSubject()
{
    string strCondition = null;
    if (ddlClassID.SelectedIndex > 0)
        strCondition += " And ClassID = '" + ddlClassID.SelectedValue + "'";
    else
    {
        if (ddlScienceID.SelectedIndex > 0)
            strCondition = " And ScienceID = '" + ddlScienceID.SelectedValue + "'";
        if (ddlCourseID.SelectedIndex > 0)
            strCondition += " And CourseID = '" + ddlCourseID.SelectedValue + "'";
    }

    if (strCondition != null)
        strCondition = strCondition.Substring(5);
    else
        strCondition = "";

    DataTable dtb = this.DtbClassSubject.Copy();
    dtb.DefaultView.RowFilter = strCondition;
    dtb = dtb.DefaultView.ToTable();
    rptClassSubject.DataSource = dtb;
    rptClassSubject.DataBind();
}

#endregion

